:param inv: input string
:param replace_with: string to replace matching parenthesis with
:return: input string without first set of matching parentheses
"""
def remove_parentheses(inv: str, replace_with: str = '') -> str {
    k = 0;
    out = '';
    for c in inv {
        if c == '(' {
            k += 1;
        } elif c == ')' {
            k -= 1;
            if k == 0 {
                out += replace_with;
            }
        } elif k == 0 {
            out += c;
        }
    }
