glob TIME_BINS = [0, 40000, 80000, 120000, 160000, 200000];

"""An function used to get the correct 4 hour interval for the TIME_BIN column

Takes a dataframe and creates a column with the times binned by every 4 hours

Args:
    time (int): A time int representation in the format hhmmss
    Ex: noon would be represented as 120000
Returns:
    output (float): The 4 hour time interval that the integer input time belongs to
"""
def get_range(time: int) -> float {
    prev = 0;
    output = 0.0;
    for h in TIME_BINS {
        if time <= h and time > prev {
            output = float(h / 10000);
            return output;
        } elif time == 200000 {
            output = float(200000 / 10000);
            return output;
        } elif time > float(200000) {
            output = float(24);
            return output;
        } elif time == 0 {
            output = float(24);
        }
    }
    return output;
}

""" Converts Y parameters into h-parameters. ABCD-parameters should be in the form [[f,Y11,Y12,Y21,Y22],...]
Returns data in the form
[[f,h11,h12,h21,h22],...]
"""
def YFrequencyList_to_HFrequencyList(y_frequency_list: list[list[float]]) -> list[list[float]] {
    h_frequency_list = [];
    for row in y_frequency_list[:] {
        [frequency, Y11, Y12, Y21, Y22] = row;
        h11 = 1 / Y11;
        h12 = -1 * Y12 / Y11;
        h21 = Y21 / Y11;
        h22 = (Y11 * Y22 - Y12 * Y21) / Y11;
        h_frequency_list.append([frequency, h11, h12, h21, h22]);
    }
    return h_frequency_list;
}

"""This remap ("recursive map") function is used to traverse and
transform the dictionary keys of arbitrarily nested structures.
List comprehensions do not recurse, making it tedious to apply
transforms to all keys in a tree-like structure.

A common issue for `moto` is changing the casing of dict keys:

>>> remap_nested_keys({'KeyName': 'Value'}, camelcase_to_underscores)
{'key_name': 'Value'}

Args:
    root: The target data to traverse. Supports iterables like
        list, tuple, and dict.
    key_transform (callable): This function is called on every
        dictionary key found in root.
"""
def remap_nested_keys(`root: any, key_transform: any) -> any {
    if isinstance(`root, (`list, `tuple)) {
        return [remap_nested_keys(item, key_transform) for item in `root];
    }
    if isinstance(`root, `dict) {
        return {
            key_transform(k): remap_nested_keys(v, key_transform)
            for (k, v) in `root.items()
        };
    }
    return `root;
}

