"""Returns whether identity is pandigital"""
def is_pandigital(a: int, b: int, c: int) -> bool {
    digits = [int(d) for d in str(a) + str(b) + str(c)];
    if len(digits) != 9 {
        return False;
    }
    if 0 in digits {
        return False;
    }
    while digits {
        d = digits.pop(0);
        if d in digits {
            return False;
        }
    }
    return True;
}
